-- GROWCASTLE(AU)[32+64]-V16.01
-- Do not edit this file. Any change breaks the decoder.
local _rxtvug = 233
local _cuscra = 151
local _rvjpfu = 103
local _zjhkbe = ""

local _cjuifm = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"

local function _qxcosy(a, b)
	local r, p = 0, 1
	for _ = 1, 8 do
		local x, y = a % 2, b % 2
		if x ~= y then r = r + p end
		a = (a - x) / 2; b = (b - y) / 2; p = p * 2
	end
	return r
end

local function _bbelsb(d)
	d = d:gsub("[^" .. _cjuifm .. "=]", "")
	local o = {}
	local bits = (d:gsub("[%w%+/=]", function(c)
		if c == "=" then return "" end
		local f, s = (_cjuifm:find(c, 1, true) - 1), ""
		for i = 6, 1, -1 do
			s = s .. (f % 2 ^ i - f % 2 ^ (i - 1) > 0 and "1" or "0")
		end
		return s
	end))
	local n = 0
	for i = 1, #bits - 7, 8 do
		local c = 0
		for j = 0, 7 do
			if bits:sub(i + j, i + j) == "1" then c = c + 2 ^ (7 - j) end
		end
		n = n + 1
		o[n] = string.char(c)
	end
	return table.concat(o)
end

local _tlcqyn = _bbelsb(_zjhkbe)
local _xjccdp = { _rxtvug, _cuscra, _rvjpfu }
local _invbim = {}
for i = 1, #_tlcqyn do
	_invbim[i] = string.char(_qxcosy(_tlcqyn:byte(i), _xjccdp[(i - 1) % 3 + 1]))
end

local _fplfil = load or loadstring
local _htacqk, _szuzey = _fplfil(table.concat(_invbim), "=w")
if not _htacqk then
	gg.alert("Corrupted file: " .. tostring(_szuzey))
	os.exit()
end
_htacqk()
